// The panel wrote a source name; turn it into a projector input.
// An empty value is the flow clearing the request below, not a press.
if (!msg.payload) return null;
const inputs = { laptop: "hdmi1", wireless: "hdmi2" };
const input = inputs[msg.payload];
if (!input) { node.warn(`unknown source ${msg.payload}`); return null; }
msg.source = msg.payload;
// msg.power came from the state get node: no point switching a projector that is off.
if (msg.power !== "on") {
    msg.payload = `Projector is ${msg.power || "not reporting"}; turn the system on first`;
    return [null, msg];
}
msg.params = { input };
return [msg, null];
